import java.util.*;

class KthTracker {
    private final int k;
    private final PriorityQueue<Integer> heap = new PriorityQueue<>(); // min-heap of the k largest

    public KthTracker(int k, int[] nums) {
        this.k = k;
        for (int x : nums) add(x);
    }

    public int add(int val) {
        heap.offer(val);
        if (heap.size() > k) heap.poll();   // drop the smallest, keep top k
        return heap.peek();                  // k-th largest
    }
}

