    def __init__(self, k: int, nums: List[int]):
        self.k = k
        self.h = []
        for x in nums: self.add(x)
    def add(self, val: int) -> int:
        heappush(self.h, val)
        if len(self.h) > self.k: heappop(self.h)
        return self.h[0]

