class KthTracker {
  constructor(k, nums) { this.k = k; this.a = nums.slice().sort((x, y) => y - x); }
  add(val) {
    let lo = 0, hi = this.a.length;
    while (lo < hi) { const m = (lo + hi) >> 1; if (this.a[m] > val) lo = m + 1; else hi = m; }
    this.a.splice(lo, 0, val);
    if (this.a.length > this.k) this.a.length = this.k;
    return this.a[this.k - 1];
  }
}
